import React, { useState } from 'react';

function App() {
  const [friends, setFriends] = useState([
    { name: 'Sangavi', balance: -70 },
    { name: 'Max', balance: -180 },
    { name: 'Annie', balance: 10 },
    { name: 'Rajeshwari', balance: 1500 }
  ]);
  const [selected, setSelected] = useState(null);
  const [bill, setBill] = useState('');
  const [yourExp, setYourExp] = useState('');
  const [friendExp, setFriendExp] = useState('');

  function splitBill() {
    const total = parseFloat(bill);
    const yours = parseFloat(yourExp);
    const theirs = parseFloat(friendExp);

    if (isNaN(total) || isNaN(yours) || isNaN(theirs)) return;
    if (yours + theirs !== total || !selected) return;

    const youPaidMore = yours - theirs;

    setFriends((prev) =>
      prev.map((f) =>
        f.name === selected
          ? { ...f, balance: f.balance + youPaidMore }
          : f
      )
    );

    setBill('');
    setYourExp('');
    setFriendExp('');
    setSelected(null);
  }

  return (
    <div>
      <h1>Have Food 🍲, Pay 💰, then Split ❌</h1>
      <section>
      <ul>
        {friends.map((f) => (
          <li key={f.name}>
            {f.name}:{' '}
            {f.balance < 0
              ? `You owe ₹${-f.balance}`
              : f.balance > 0
              ? `${f.name} owes you ₹${f.balance}`
              : "Settled up"}
            <button onClick={() => setSelected(f.name)} clas>Select</button>
          </li>
        ))}
      </ul>
      </section>

      {selected && (
        <div>
          <h2>Split A Bill With {selected}</h2>
          <input
            placeholder="Bill Value"
            value={bill}
            onChange={e => setBill(e.target.value)}
          />
          <input
            placeholder="Your Expense"
            value={yourExp}
            onChange={e => setYourExp(e.target.value)}
          />
          <input
            placeholder="Your Friend Expense"
            value={friendExp}
            onChange={e => setFriendExp(e.target.value)}
          />
          <button onClick={splitBill}>Split Bill</button>
        </div>
      )}
    </div>
  );
}

export default App;
